"""Create a local IO-VNBD acquisition/provenance inventory without reading locked data."""
from __future__ import annotations
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RAW = ROOT / "data" / "raw" / "io_vnbd"
PROC = ROOT / "data" / "processed" / "io_vnbd"
OUT = ROOT / "artifacts" / "evaluation"
LOCKED = {"vta1a", "vta1b", "y1"}

def inventory_paths(root: Path) -> dict:
    files = [p for p in root.rglob("*") if p.is_file()]
    csv = [p for p in files if p.suffix.lower() == ".csv"]
    def display(path: Path) -> str:
        try:
            return str(path.relative_to(ROOT))
        except ValueError:
            return str(path)
    return {"root": display(root), "file_count": len(files), "extensions": {e: sum(p.suffix.lower() == e for p in files) for e in sorted({p.suffix.lower() for p in files})}, "csv_count": len(csv), "csv_paths": [display(p) for p in sorted(csv)]}

def trip_name(path: Path) -> str:
    return path.stem[2:].lower() if path.stem[:2].lower() in {"s-", "v-"} else ""

def main() -> None:
    raw = inventory_paths(RAW); processed = inventory_paths(PROC)
    raw_csv = [Path(p) for p in raw["csv_paths"]]
    safe = [p for p in raw_csv if trip_name(p) not in LOCKED]
    s = {}; v = {}
    for p in safe:
        (s if p.stem.lower().startswith("s-") else v if p.stem.lower().startswith("v-") else {})[trip_name(p)] = s.get(trip_name(p), []) + [str(p)] if p.stem.lower().startswith("s-") else v.get(trip_name(p), []) + [str(p)] if p.stem.lower().startswith("v-") else []
    report = {"verdict": "C", "verdict_text": "IO-VNBD alone does not provide enough authoritative metadata for deterministic reconstruction; a new independently synchronized recording is required unless the authors supply missing metadata.", "scope": {"locked_trip_content_opened": False, "locked_trip_names_excluded_from_content_inventory": ["Vta1a", "Vta1b", "Y1"], "train_validation_content_inventory": True}, "local_inventory": {"raw": raw, "processed": processed, "raw_structure": ["Synchronised V abd S datasets/Categorised IOVNB Dataset/<scenario>/<trip>", "Synchronised V abd S datasets/Uncategorised IOVNB Dataset/S-Dataset", "Synchronised V abd S datasets/Uncategorised IOVNB Dataset/V-Dataset"], "raw_formats": ["CSV", "JPG"], "processed_formats": ["CSV"], "safe_source_csv_count": len(safe), "safe_smartphone_csv_count": sum(p.stem.lower().startswith("s-") for p in safe), "safe_vehicle_csv_count": sum(p.stem.lower().startswith("v-") for p in safe)}, "pairing": {"available_in_synchronized_tree": "S-/V- filename pairs for the audited train/validation trips", "metadata_file": "none in the local synchronized source tree", "duplicate_tree_copies": "categorized and uncategorized copies exist; prior checks found audited duplicate vehicle files byte-identical", "prepare_io_vnbd_files": "scripts/prepare_io_vnbd.py discovers S-/V- files recursively, truncates to min length, pairs by row index, then sorts/deduplicates phone elapsed time and resamples"}, "columns": {"phone": ["TIME SINCE START (ms)", "DATE (YYYY-MO-DD HH-MI-SS_SSS)", "ACCELEROMETER X/Y/Z", "GRAVITY X/Y/Z", "GYROSCOPE X/Y/Z or Yaw/Pitch/Roll", "ORIENTATION", "GPS"], "vehicle": ["Time Since Start of Day (seconds)", "Sample period (seconds)", "GPS Velocity", "Wheel Speed", "Yaw Rate", "Indicated Vehicle Speed", "Indicated Longitudinal/Lateral Acceleration"]}, "official_evidence": [{"classification": "A", "claim": "The paper states simultaneously collected S/V pairs were manually synchronized where possible and stored in the synchronized folder.", "source": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7907232/"}, {"classification": "A", "claim": "The paper documents the phone holder, intended axis alignment, nominal 10 Hz acquisition, and vehicle CAN/VBOX fields.", "source": "https://pmc.ncbi.nlm.nih.gov/articles/PMC7907232/"}, {"classification": "D", "claim": "No author-published numeric synchronization map, dropped-row correspondence, fixed rotation matrix, or reproducible preprocessing algorithm was found in the official repository/paper materials.", "source": "https://github.com/onyekpeu/IO-VNBD"}], "provenance_gap_table": [{"information": "S/V pair identity", "available": True, "authoritative": "partially", "where": "synchronized folder and matching filenames", "confidence": "high", "needed": True}, {"information": "synchronization offset/drift", "available": False, "authoritative": False, "where": "not distributed", "confidence": "high", "needed": True}, {"information": "dropped samples/exact mapping", "available": False, "authoritative": False, "where": "not distributed", "confidence": "high", "needed": True}, {"information": "phone/vehicle timestamps", "available": True, "authoritative": "raw fields only", "where": "CSV columns", "confidence": "high", "needed": True}, {"information": "phone-to-vehicle rotation", "available": False, "authoritative": False, "where": "only physical setup/figures", "confidence": "high", "needed": True}, {"information": "mounting orientation", "available": "physical intention only", "authoritative": "partially", "where": "paper figures", "confidence": "medium", "needed": True}, {"information": "axis signs/conventions", "available": "partially", "authoritative": "partially", "where": "paper tables/figures and fields", "confidence": "medium", "needed": True}, {"information": "target-speed provenance", "available": True, "authoritative": "field identity only", "where": "vehicle CSV and paper table", "confidence": "medium", "needed": True}, {"information": "independent velocity reference", "available": True, "authoritative": "vehicle reference field", "where": "GPS Velocity column", "confidence": "medium", "needed": True}, {"information": "resampling method", "available": False, "authoritative": False, "where": "not documented", "confidence": "high", "needed": True}], "minimum_author_authority_package": ["per-pair synchronization event/offset and drift or sample-index correspondence", "dropped-row/start-stop map", "numeric phone-to-vehicle rotation and sign convention per recording", "Variant A gyro axis definition", "target/reference provenance and any applied filtering/resampling"], "new_recording_protocol": {"phone": "raw accelerometer, gravity, gyroscope, magnetometer at >=100 Hz preferred; retain Android event timestamps and wall-clock timestamps", "reference": "vehicle CAN/VBOX longitudinal/lateral acceleration and yaw rate at >=100 Hz or shared hardware-clock IMU", "speed": "wheel-speed or VBOX/GNSS velocity with documented provenance", "sync": "shared hardware trigger or visible/acoustic synchronization pulse recorded by both systems at start and end; retain trigger timestamps", "mount": "rigid holder; record phone pose relative to vehicle axes with a measured calibration fixture", "maneuvers": ["30 s stationary at start/end", "straight cruising", "several acceleration/braking events", "left/right turns and roundabout", "rough-road/bump segment", "GNSS-denied portion if relevant"], "metadata": ["device/model/firmware", "sensor rates and event timestamps", "vehicle/reference frame definition", "mount pose matrix", "trigger times", "filtering/resampling settings", "trip/recording group ID"]}, "corpus_schema": ["raw_source: immutable original files and hashes", "synchronized: common monotonic clock plus correspondence/quality flags", "calibrated: vehicle-frame six channels plus persisted rotation/provenance", "labels: indicated speed with provenance and independent references", "quality: reset/gap/observability/frame/sync flags", "splits: complete recording group separation; locked benchmark immutable"], "repository_history": {"official_repository": "4 commits shown; no releases/tags or synchronization/calibration implementation identified", "local_history": "Percorsa history contains local adapters/preparation scripts, not the authors' missing metadata; no evidence changes the official-source conclusion"}, "recommendation": "Contacting the authors is worthwhile, specifically requesting the minimum authority package. Engineering should next create a separate Percorsa synchronized pilot recording with hardware/visible start-end triggers and measured phone pose; do not regenerate IO-VNBD or train until that provenance path is validated."}
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "io_vnbd_acquisition_inventory.json").write_text(json.dumps(report, indent=2), encoding="utf-8")
    (OUT / "io_vnbd_acquisition_report.md").write_text("# IO-VNBD acquisition and provenance investigation\n\n## Verdict\n\n**C — reconstruction from IO-VNBD alone is impossible under the required provenance standard.** The official material documents a manually synchronized collection and physical holder setup, but does not expose the synchronization operation, dropped-sample map, or numeric frame calibration.\n\n## Evidence\n\n- [Official IO-VNBD paper](https://pmc.ncbi.nlm.nih.gov/articles/PMC7907232/): classification A for manual synchronization where possible, nominal sampling, holder, and axis-alignment intent; classification D for a reproducible numeric procedure.\n- [Official repository](https://github.com/onyekpeu/IO-VNBD): synchronized/unsynchronized collections and README are present; no synchronization/calibration implementation or metadata was found.\n\nThe local source tree contains CSV/JPG data under categorized and uncategorized synchronized folders. The current preparation script discovers S/V files recursively, truncates to equal length, pairs by row index, then sorts/deduplicates/resamples. That is a local assumption, not an author-provided correspondence contract.\n\n## Missing authority\n\nThe required missing package is: per-pair offset/drift or exact sample mapping, dropped-row/start-stop map, numeric phone-to-vehicle rotation, Variant A gyro axis definition, and target/reference filtering/resampling provenance.\n\n## New recording\n\nUse raw phone IMU timestamps plus a reference vehicle IMU/CAN/VBOX stream, a shared hardware or visible/acoustic start/end trigger, a rigid measured mount pose, documented speed reference, stationary periods, straight cruising, acceleration/braking, turning, bumps, and optional GNSS-denied driving. Save all event timestamps, trigger times, pose matrices, rates, device metadata, hashes, and recording group IDs.\n\n## Decision\n\nContact the IO-VNBD authors for the missing authority package, but begin engineering a new independently synchronized Percorsa pilot. Do not regenerate or train from the current IO-VNBD corpus.\n", encoding="utf-8")
    print(json.dumps({"verdict": "C", "raw_files": raw["file_count"], "processed_files": processed["file_count"], "locked_content_opened": False}, indent=2))

if __name__ == "__main__":
    main()
